-- Zonas (spec .scratch/ubicacion-por-punto/spec.md, «zones» y «RPCs»): lista de pueblos, playas y barrios con un punto,
-- para el selector «Zona» del paso de ubicación. Lectura pública de las activas (sin la geometría: lat/lng se generan
-- del punto); escrituras solo del admin (is_admin() exige aal2). `zones_near` da las de un radio, la más cercana primero.
-- Primera versión: borrador de OpenStreetMap del Caribe (.scratch/ubicacion-por-punto/zonas.md, scripts/osm-zonas/
-- borrador.mjs), cargado sin revisar por Daniel; sus cambios van en una migración nueva (docs/antes-de-produccion.md).

create table public.zones (
  id text primary key check (id ~ '^[1-7][0-9]{2}-[a-z0-9-]+$'),
  name text not null check (char_length(name) between 1 and 60),
  canton_code text not null references geo.admin_names(code),
  point extensions.geometry(Point, 4326) not null,
  lat double precision generated always as (extensions.ST_Y(point)) stored,
  lng double precision generated always as (extensions.ST_X(point)) stored,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index zones_point on public.zones using gist (point);

alter table public.zones enable row level security;
create policy zones_read on public.zones for select to anon, authenticated using (active);
create policy zones_admin on public.zones for all to authenticated using (is_admin()) with check (is_admin());

revoke all on public.zones from public, anon, authenticated;
grant select (id, name, canton_code, lat, lng, active) on public.zones to anon, authenticated;
grant insert, update, delete on public.zones to authenticated; -- RLS: solo el admin (aal2)

-- Zonas activas a p_km o menos del punto (entre 0 y 50 km), la más cercana primero; distance_m en metros enteros.
create function public.zones_near(p_lat double precision, p_lng double precision, p_km double precision default 5)
  returns table (id text, name text, distance_m integer)
  language sql stable security definer set search_path = public, extensions
as $$
  with pt as (select ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography g)
  select z.id, z.name, round(ST_Distance(z.point::geography, pt.g))::integer as distance_m
  from public.zones z, pt
  where z.active
    and ST_DWithin(z.point::geography, pt.g, least(greatest(coalesce(p_km, 5), 0), 50) * 1000)
  order by distance_m, z.name;
$$;
revoke execute on function public.zones_near(double precision, double precision, double precision) from public;
grant execute on function public.zones_near(double precision, double precision, double precision) to anon, authenticated;

-- Datos: generado con `node scripts/osm-zonas/borrador.mjs --sql <archivo>` (OpenStreetMap, Overpass 2026-10-28; ODbL 1.0,
-- © colaboradores de OpenStreetMap). Entran también las filas «revisar» de zonas.md.

do $$
declare
  missing text;
begin
  select string_agg(r.id, ', ') into missing
  from unnest(array['704-puerto-viejo', '704-playa-negra', '704-cocles', '704-playa-chiquita', '704-punta-uva',
                    '704-manzanillo', '704-cahuita', '704-hone-creek', '704-bribri', '701-limon-centro']) r(id)
  where not exists (select 1 from public.zones z where z.id = r.id);
  if missing is not null then
    raise exception 'Faltan zonas obligatorias: %', missing;
  end if;
end $$;
